#include "aig/gia/giaFx.c"
int main(void){Gia_Man_t *g;Dec_Graph_t *d;Dec_Edge_t root;int n,leaf,phase,signal,unused,i,a,b,lit;int vars[8];
 for(signal=0;signal<2;++signal){g=Gia_ManStart(8);d=signal?Dec_GraphCreateConst1():Dec_GraphCreateConst0();printf("constant %d lit%d objs%d\n",signal,Gia_ManGraphToAig(g,d),Gia_ManObjNum(g));Dec_GraphFree(d);Gia_ManStop(g);}
 for(n=1;n<=4;++n)for(leaf=0;leaf<n;++leaf)for(phase=0;phase<2;++phase)for(signal=0;signal<3;++signal)for(unused=0;unused<2;++unused){if(unused && n<2)continue;g=Gia_ManStart(32);for(i=0;i<n;++i)vars[i]=Gia_ManAppendCi(g);d=Dec_GraphCreateLeaf(leaf,n,phase);if(unused){Dec_GraphAddNodeAnd(d,Dec_EdgeCreate(0,0),Dec_EdgeCreate(1,0));Dec_GraphSetRoot(d,Dec_EdgeCreate(leaf,phase));}Dec_GraphVar(d)->iFunc=signal<2?signal:vars[leaf];lit=Gia_ManGraphToAig(g,d);printf("var n%d leaf%d phase%d signal%d unused%d lit%d objs%d\n",n,leaf,phase,signal,unused,lit,Gia_ManObjNum(g));Dec_GraphFree(d);Gia_ManStop(g);}
 for(n=2;n<=5;++n)for(a=0;a<2;++a)for(b=0;b<2;++b)for(phase=0;phase<2;++phase){g=Gia_ManStart(32);for(i=0;i<n;++i)vars[i]=Gia_ManAppendCi(g);d=Dec_GraphCreate(n);Dec_GraphNode(d,0)->iFunc=vars[0];Dec_GraphNode(d,1)->iFunc=vars[1];root=Dec_GraphAddNodeAnd(d,Dec_EdgeCreate(0,a),Dec_EdgeCreate(1,b));root.fCompl^=phase;Dec_GraphSetRoot(d,root);Gia_ManHashAlloc(g);lit=Gia_ManGraphToAig(g,d);printf("and n%d a%d b%d phase%d lit%d node%d objs%d\n",n,a,b,phase,lit,Dec_GraphNode(d,root.Node)->iFunc,Gia_ManObjNum(g));Dec_GraphFree(d);Gia_ManStop(g);}
 return 0;}
